    int a[1005]; for(int i=0; i<n; i++) scanf("%d", &a[i]);
    if(n==1) { pa(a,n); return 0; }
    for(int gap=n/2; gap>0; gap/=2) {
        for(int i=gap; i<n; i++) {
            int temp=a[i], j;
            for(j=i; j>=gap && a[j-gap]>temp; j-=gap) a[j]=a[j-gap];
            a[j]=temp;
        }
        pa(a,n);
    }
    return 0;
}

